mapper.select:
SELECT c.*
FROM sys_flow_cc c
WHERE c.tenant_id = #{tenantId}
  AND c.cc_user_id = #{userId}
  AND c.status = 0

  AND c.is_read = #{isRead}


  AND (
      c.title LIKE CONCAT('%', #{title}, '%')
      OR c.content LIKE CONCAT('%', #{title}, '%')
      OR c.process_def_key LIKE CONCAT('%', #{title}, '%')
      OR c.business_key LIKE CONCAT('%', #{title}, '%')
  )

ORDER BY c.cc_time DESC, c.id DESC

SELECT c.* FROM sys_flow_cc c WHERE c.tenant_id = #{tenantId} AND c.send_user_id = #{userId}
AND ( c.title LIKE CONCAT('%', #{title}, '%') OR c.content LIKE CONCAT('%', #{title}, '%') OR c.process_def_key LIKE CONCAT('%', #{title}, '%') OR c.business_key LIKE CONCAT('%', #{title}, '%') )
ORDER BY c.cc_time DESC, c.id DESC

SELECT COUNT(1)
FROM sys_flow_cc c
WHERE c.cc_user_id = #{userId}
  AND c.tenant_id = #{tenantId}
  AND c.is_read = 0
  AND c.status = 0

mapper.update:
UPDATE sys_flow_cc
SET is_read = 1,
    read_time = #{readTime},
    update_time = #{readTime}
WHERE tenant_id = #{tenantId}
  AND cc_user_id = #{userId}
  AND is_read = 0
  AND status = 0

mapper.select:
SELECT COUNT(1)
FROM sys_flow_cc c
WHERE c.process_instance_id = #{processInstanceId}
  AND c.tenant_id = #{tenantId}
  AND (c.send_user_id = #{userId} OR (c.cc_user_id = #{userId} AND c.status = 0))

mapper.delete:
DELETE FROM sys_flow_cc
WHERE process_instance_id = #{processInstanceId}
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE sys_flow_cc
SET status = #{status}, revoke_by = #{senderId}, revoke_time = #{revokeTime},
    revoke_reason = #{reason}, update_time = #{revokeTime}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND send_user_id = #{senderId}
  AND status = 0
